package com.alsafa.native4;
import android.app.Activity;import android.content.ContentValues;import android.content.Intent;import android.os.Bundle;import android.widget.TextView;import com.alsafa.native4.core.CoreDb;import com.alsafa.native4.core.Native4AutoSync;import com.alsafa.native4.sync.OutboxDb;
public class MainActivity extends Activity{
 private static final String TEST_STORE="test-native4-android-alpha";private OutboxDb outboxDb;private CoreDb coreDb;private TextView status;
 @Override public void onCreate(Bundle state){super.onCreate(state);Native4Safety.requireIsolatedStore(TEST_STORE);setContentView(R.layout.activity_main);status=findViewById(R.id.status);outboxDb=new OutboxDb(this);recoverMissingDefaultDatabaseFailures();outboxDb.recoverInterrupted();coreDb=new CoreDb(this);recoverCoreInterrupted();findViewById(R.id.openSimple).setOnClickListener(v->startActivity(new Intent(this,SimpleHomeActivity.class)));findViewById(R.id.openFull).setOnClickListener(v->startActivity(new Intent(this,AdvancedHomeActivity.class)));findViewById(R.id.openAdvisor).setOnClickListener(v->status.setText("مستشار اختيار الساعة سينقل كصفحة مستقلة في الخطوة التالية"));TabletTouchUi.apply(this,findViewById(R.id.rootContent));}
 @Override protected void onResume(){super.onResume();if(coreDb!=null)Native4AutoSync.request(this,coreDb,null);}
 private void recoverMissingDefaultDatabaseFailures(){ContentValues v=new ContentValues();v.put("state","FAILED_RETRYABLE");v.put("last_error","تم إنشاء Firestore (default) ونشر القواعد؛ أعيدت العملية القديمة للمحاولة بنفس operationId");outboxDb.getWritableDatabase().update("outbox",v,"state='FAILED_PERMANENT' AND last_error LIKE ?",new String[]{"%database (default) does not exist for project alsafa-native%"});}
 private void recoverCoreInterrupted(){ContentValues v=new ContentValues();v.put("state","RETRY");v.put("last_error","استعادة آمنة بعد توقف التطبيق أثناء الإرسال");coreDb.db().update("outbox",v,"state='SENDING'",null);}
}